def transform(grid):
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]

    # The 5 marks the starting point of the path.
    start_r, start_c = 0, 0
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 5:
                start_r, start_c = r, max(0, min(6, c - 8))
                out[start_r][start_c] = 5

    # Each 3x3 tile encodes a directed stroke. Read down the left
    # column of tiles, then down the right column.
    tiles = []
    for left in (0, 4):
        for top in range(0, h - 2, 4):
            cells = [(r - top, c - left, grid[r][c])
                     for r in range(top, top + 3)
                     for c in range(left, left + 3)
                     if grid[r][c] != 0]
            if not cells:
                continue
            color = cells[0][2]
            shape = {(r, c) for r, c, _ in cells}

            if shape == {(0, 0), (0, 1), (1, 0), (1, 2), (2, 1)}:
                tiles.append((color, "right", 3))
            elif shape == {(0, 0), (0, 2), (1, 0), (1, 2),
                           (2, 0), (2, 1), (2, 2)}:
                tiles.append((color, "left", 2))
            elif shape == {(0, 0), (0, 2), (1, 1), (2, 1)}:
                tiles.append((color, "down", 2))
            elif shape == {(0, 0), (0, 1), (0, 2), (1, 1),
                           (2, 0), (2, 2)}:
                tiles.append((color, "left", 4))

    r, c = start_r, start_c
    for color, direction, length in tiles:
        if direction == "down":
            for rr in range(r + 1, r + length + 1):
                if 0 <= rr < h and 0 <= c < 7:
                    out[rr][c] = color
            r += length
        else:
            dr = 1 if direction == "right" else -1
            rr = r + 1
            for i in range(length):
                cc = c + dr * i
                if 0 <= rr < h and 0 <= cc < 7:
                    out[rr][cc] = color
            r = rr
            c += dr * (length - 1)

    return out
